"use client";

import { useAccountContext } from "@/features/common/contexts/AccountContext";
import { SettingContainer } from "@/features/standard/setting/components/containers/SettingContainer";
import { cn } from "@/utils/cn";
import { Modules } from "@carlonicora/nextjs-jsonapi";
import { usePageUrlGenerator } from "@carlonicora/nextjs-jsonapi/client";
import {
  ContentTitle,
  PageContentContainer,
  SecurityContainer,
  UserStanadaloneDetails,
} from "@carlonicora/nextjs-jsonapi/components";
import { useCurrentUserContext } from "@carlonicora/nextjs-jsonapi/contexts";
import { LucideIcon, Shield, UserIcon } from "lucide-react";
import { useLocale, useTranslations } from "next-intl";
import { ReactNode } from "react";

type SidebarItem = {
  id: string;
  icon: LucideIcon;
  label: string;
  container: ReactNode;
};

export default function AccountContainer() {
  const { section, setSection } = useAccountContext();
  const t = useTranslations();
  const locale = useLocale();
  const generateUrl = usePageUrlGenerator();
  const { currentUser } = useCurrentUserContext();

  const sidebarItems: SidebarItem[] = [
    {
      id: "profile",
      icon: UserIcon,
      label: t(`common.settings`, { item: "profile" }),
      container: <UserStanadaloneDetails user={currentUser} />,
    },
    {
      id: "security",
      icon: Shield,
      label: t("common.settings", { item: "security" }),
      container: <SecurityContainer />,
    },
    {
      id: "setting",
      icon: Modules.Setting.icon,
      label: t("common.settings", { item: "setting" }),
      container: <SettingContainer />,
    },
  ];

  const selectedItem = sidebarItems.find((item) => item.id === section) || sidebarItems[0];

  return (
    <PageContentContainer
      header={<ContentTitle element={t("common.settings", { item: "account" })} />}
      details={
        <nav className="space-y-4">
          <div>
            {sidebarItems.map((item) => {
              const Icon = item.icon;
              return (
                <button
                  key={item.id}
                  onClick={() => {
                    setSection(item.id as "profile" | "security" | "setting");
                    window.history.replaceState(
                      null,
                      "",
                      generateUrl({ page: "/account", id: item.id, language: locale }),
                    );
                  }}
                  className={cn(
                    "flex w-full items-center gap-3 rounded-md px-3 py-2 text-sm transition-colors",
                    selectedItem?.id === item.id
                      ? "bg-secondary text-secondary-foreground"
                      : "text-muted-foreground hover:text-foreground hover:bg-secondary/50",
                  )}
                >
                  <Icon className="h-4 w-4" />
                  {item.label}
                </button>
              );
            })}
          </div>
        </nav>
      }
      content={selectedItem ? selectedItem.container : null}
    />
  );
}

"use client";

import VersionDisplay from "@/features/common/components/navigations/VersionDisplay";
import { OnboardingTrigger } from "@/features/onboarding";
import { usePageUrlGenerator } from "@carlonicora/nextjs-jsonapi/client";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuGroup,
  DropdownMenuItem,
  DropdownMenuLabel,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
  Link,
  ModeToggleSwitch,
  NotificationModal,
  SidebarMenu,
  SidebarMenuButton,
  SidebarMenuItem,
  UserAvatar,
  useSidebar,
} from "@carlonicora/nextjs-jsonapi/components";
import { useCurrentUserContext } from "@carlonicora/nextjs-jsonapi/contexts";
import { UserInterface } from "@carlonicora/nextjs-jsonapi/core";
import { RoleId } from "@{{name}}/shared";
import { ChevronsUpDown, LogOut, SettingsIcon, Shield } from "lucide-react";
import { useTranslations } from "next-intl";

type UserSidebarFooterProps = {
  notificationModalOpen: boolean;
  setNotificationModalOpen: (open: boolean) => void;
};

export function UserSidebarFooter({ notificationModalOpen, setNotificationModalOpen }: UserSidebarFooterProps) {
  const { currentUser, hasRole } = useCurrentUserContext<UserInterface>();
  const { isMobile } = useSidebar();
  const generateUrl = usePageUrlGenerator();
  const t = useTranslations();

  const logOut = async () => {
    window.location.href = generateUrl({ page: `/logout` });
  };

  return (
    <SidebarMenu>
      <OnboardingTrigger />

      {currentUser && !hasRole(RoleId.Administrator) && (
        <SidebarMenuItem>
          <NotificationModal isOpen={notificationModalOpen} setIsOpen={setNotificationModalOpen} />
        </SidebarMenuItem>
      )}

      <SidebarMenuItem className="-ml-0.5 w-full">
        {currentUser && (
          <DropdownMenu>
            <DropdownMenuTrigger className={`w-full`}>
              <SidebarMenuButton
                render={<div />}
                className="data-[state=open]:bg-sidebar-accent data-[state=open]:text-sidebar-accent-foreground flex w-full items-center justify-between"
              >
                <UserAvatar user={currentUser} className="h-5 w-5" showTooltip={false} />
                <div className="grid w-full flex-1 text-left text-sm leading-tight">
                  <span className="truncate font-semibold">{currentUser.name}</span>
                  <span className="truncate text-xs">{currentUser.email}</span>
                </div>
                <ChevronsUpDown className="ml-auto size-4" />
              </SidebarMenuButton>
            </DropdownMenuTrigger>
            <DropdownMenuContent
              className="w-[--radix-dropdown-menu-trigger-width] min-w-56 rounded-lg"
              side={isMobile ? "bottom" : "right"}
              align="end"
              sideOffset={4}
            >
              <DropdownMenuGroup>
                <DropdownMenuLabel className="p-0 font-normal">
                  <div className="flex items-center gap-2 px-1 py-1.5 text-left text-sm">
                    <div className="grid flex-1 text-left text-sm leading-tight">
                      <span className="truncate font-semibold">{currentUser.name}</span>
                      <span className="truncate text-xs">{currentUser.email}</span>
                    </div>
                  </div>
                </DropdownMenuLabel>
              </DropdownMenuGroup>
              <DropdownMenuSeparator />
              <DropdownMenuGroup>
                <DropdownMenuLabel>
                  <VersionDisplay />
                </DropdownMenuLabel>
              </DropdownMenuGroup>
              <DropdownMenuSeparator />
              <DropdownMenuGroup>
                <DropdownMenuItem onSelect={(event) => event.preventDefault()}>
                  <ModeToggleSwitch />
                  {t(`common.theme`)}
                </DropdownMenuItem>
              </DropdownMenuGroup>
              <DropdownMenuSeparator />
              <DropdownMenuGroup>
                {(hasRole(RoleId.CompanyAdministrator) || hasRole(RoleId.Administrator)) && (
                  <Link href={generateUrl({ page: `/settings` })} prefetch={false}>
                    <DropdownMenuItem>
                      <SettingsIcon />
                      {t(`common.settings`, { item: "company" })}
                    </DropdownMenuItem>
                  </Link>
                )}

                {/* <Link href={generateUrl({ page: Modules.User, id: currentUser.id })}>
                  <DropdownMenuItem>
                    <UserIcon />
                    {t(`common.settings`, { item: "profile" })}
                  </DropdownMenuItem>
                </Link> */}
                <Link href={generateUrl({ page: "/account" })}>
                  <DropdownMenuItem>
                    <Shield />
                    {t("common.settings", { item: "account" })}
                  </DropdownMenuItem>
                </Link>
              </DropdownMenuGroup>
              <DropdownMenuSeparator />
              <DropdownMenuGroup>
                <DropdownMenuItem onClick={logOut}>
                  <LogOut />
                  {t(`auth.buttons.logout`)}
                </DropdownMenuItem>
              </DropdownMenuGroup>
            </DropdownMenuContent>
          </DropdownMenu>
        )}
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

"use client";

import { BreadcrumbItemData } from "@carlonicora/nextjs-jsonapi";
import { usePageUrlGenerator } from "@carlonicora/nextjs-jsonapi/client";
import { SharedProvider } from "@carlonicora/nextjs-jsonapi/contexts";
import { useTranslations } from "next-intl";
import { createContext, ReactNode, useContext, useState } from "react";

type AccountSection = "security" | "setting" | "profile";

interface AccountContextType {
  section: AccountSection;
  setSection: (section: AccountSection) => void;
}

const AccountContext = createContext<AccountContextType | undefined>(undefined);

type AccountProviderProps = {
  children: ReactNode;
  initialSection?: AccountSection;
};

export const AccountProvider = ({ children, initialSection = "profile" }: AccountProviderProps) => {
  const [section, setSection] = useState<AccountSection>(initialSection);
  const generateUrl = usePageUrlGenerator();
  const t = useTranslations();

  const breadcrumb = (): BreadcrumbItemData[] => {
    const response: BreadcrumbItemData[] = [];

    response.push({
      name: t("common.settings", { item: "account" }),
      href: generateUrl({ page: "/account" }),
    });

    if (section) {
      response.push({
        name: t("common.settings", { item: section }),
        href: generateUrl({ page: `/account/${section}` }),
      });
    }

    return response;
  };

  const title = () => ({
    type: t("common.settings", { item: section ?? "account" }),
  });

  return (
    <SharedProvider value={{ breadcrumbs: breadcrumb(), title: title() }}>
      <AccountContext.Provider
        value={{
          section,
          setSection,
        }}
      >
        {children}
      </AccountContext.Provider>
    </SharedProvider>
  );
};

export const useAccountContext = (): AccountContextType => {
  const context = useContext(AccountContext);
  if (context === undefined) {
    throw new Error("useAccountContext must be used within an AccountProvider");
  }
  return context;
};
